WITH unpacked AS (SELECT id, currency, discounts, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, SLICE(tier_limits, 1, 2) AS first_two_limits, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT *, FIRST_VALUE(lowest_price) IGNORE NULLS OVER (PARTITION BY currency ORDER BY lowest_price ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_lowest_price, LAG(entry_price, 1) OVER (PARTITION BY currency ORDER BY lowest_price ASC, id ASC) prev_entry_price, AVG(lowest_price) OVER (PARTITION BY currency ORDER BY entry_price ASC, id ASC ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) lowest_price_avg_5 FROM unpacked
